(function(){
  'use strict';
  var KEY='welog-pair-sheet-v4',CONCEPT_KEY='welog-concept-sides-v1',PADDING_KEY='welog-card-padding-v2';
  var controls=document.getElementById('controls'),sheet=document.getElementById('sheet'),saveBtn=document.getElementById('printBtn'),previewBtn=document.getElementById('previewBtn');
  function readState(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){return{}}}
  function writeState(s){try{localStorage.setItem(KEY,JSON.stringify(s));return true}catch(e){return false}}

  /* Built-in fonts: unique internal family names, so old CSS cannot shadow them. */
  var defs={
    'Pretendard':['WeLog-Pretendard','https://cdn.jsdelivr.net/gh/unfail-human/BackUp-X@main/webfonts/PretendardVariable.woff2','woff2'],
    'Noto Sans KR':['WeLog-NotoSansKR','https://cdn.jsdelivr.net/gh/unfail-human/BackUp-X@main/webfonts/NotoSansKR-VariableFont_wght.woff2','woff2'],
    'KoPub Dotum Medium':['WeLog-KoPubDotum','https://cdn.jsdelivr.net/gh/unfail-human/BackUp-X@main/webfonts/KoPubWorld%20Dotum%20Medium.ttf','truetype'],
    'KoPub Batang Medium':['WeLog-KoPubBatang','https://cdn.jsdelivr.net/gh/unfail-human/BackUp-X@main/webfonts/KoPubWorld%20Batang%20Medium.ttf','truetype']
  },fontPromises={};
  function normalizeFont(v){if(/^KoPub Dotum/.test(v||''))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v||''))return'KoPub Batang Medium';if(v==='__default__'||!v)return'Pretendard';return v}
  function loadFont(name){name=normalizeFont(name);if(name==='__system__'||!defs[name]||!window.FontFace)return Promise.resolve();if(fontPromises[name])return fontPromises[name];var d=defs[name];fontPromises[name]=new FontFace(d[0],'url("'+d[1]+'") format("'+d[2]+'")',{style:'normal',weight:'100 900'}).load().then(function(face){document.fonts.add(face);return face}).catch(function(err){console.error('WeLog font load failed',name,err)});return fontPromises[name]}
  function stackFor(name){if(name==='__system__')return'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';if(defs[name])return'"'+defs[name][0]+'",sans-serif';return'"'+String(name).replace(/"/g,'')+'",sans-serif'}
  async function applyFont(value){var name=normalizeFont(value||readState().font||'Pretendard');await loadFont(name);var stack=stackFor(name);document.documentElement.style.setProperty('--app-font',stack);if(sheet){sheet.style.setProperty('font-family',stack,'important');sheet.querySelectorAll('*').forEach(function(el){el.style.setProperty('font-family',stack,'important')})}var modalSheet=document.querySelector('.welog-preview-sheet');if(modalSheet){modalSheet.style.setProperty('font-family',stack,'important');modalSheet.querySelectorAll('*').forEach(function(el){el.style.setProperty('font-family',stack,'important')})}}
  function saveFont(v){var s=readState();s.font=normalizeFont(v);writeState(s);applyFont(s.font)}
  function simplifyFontSelect(){if(!controls)return;var sel=controls.querySelector('select[data-path="font"]');if(!sel)return;var current=normalizeFont(readState().font||sel.value),built=[['Pretendard','Pretendard'],['Noto Sans KR','Noto Sans KR'],['KoPub Dotum Medium','KoPubWorld 돋움'],['KoPub Batang Medium','KoPubWorld 바탕'],['__system__','시스템 폰트']],uploads=Array.from(sel.options).filter(function(o){return o.value&&built.every(function(x){return x[0]!==o.value})&&!/^KoPub (Dotum|Batang) (Light|Bold)$/.test(o.value)}).map(function(o){return[o.value,o.textContent]});sel.innerHTML='';built.concat(uploads).forEach(function(x){if(Array.from(sel.options).some(function(o){return o.value===x[0]}))return;var o=document.createElement('option');o.value=x[0];o.textContent=x[1];sel.appendChild(o)});if(Array.from(sel.options).some(function(o){return o.value===current}))sel.value=current;else sel.value='Pretendard'}

  /* Independent concept display. */
  function readSides(){try{var a=JSON.parse(localStorage.getItem(CONCEPT_KEY)||'null');if(Array.isArray(a))return a.filter(function(x,i,z){return(x==='left'||x==='right')&&z.indexOf(x)===i})}catch(e){}var s=readState();return s.visible&&s.visible.concept&&s.conceptSide?[s.conceptSide]:[]}
  function setSide(side,on){var a=readSides(),i=a.indexOf(side);if(on&&i<0)a.push(side);if(!on&&i>=0)a.splice(i,1);localStorage.setItem(CONCEPT_KEY,JSON.stringify(a));syncChecks();renderConcepts()}
  function syncChecks(){if(!controls)return;var a=readSides();controls.querySelectorAll('input[data-concept-side]').forEach(function(c){c.checked=a.indexOf(c.dataset.conceptSide)>=0})}
  function esc(t){var d=document.createElement('div');d.textContent=t==null?'':String(t);return d.innerHTML}
  function renderConcepts(){if(!sheet)return;var s=readState(),a=readSides();sheet.querySelectorAll('.concept-block').forEach(function(n){n.remove()});a.forEach(function(side){var p=sheet.querySelector('.profile.'+side);if(!p)return;var value=s[side]&&s[side].concept||'',b=document.createElement('div');b.className='text-block concept-block';b.dataset.runtimeConcept=side;b.innerHTML='<h3>컨셉</h3><div class="formatted-lines">'+String(value).split('\n').filter(Boolean).map(function(x){return'<p>'+esc(x)+'</p>'}).join('')+'</div>';var c=p.querySelector('.commission-block');c?p.insertBefore(b,c):p.appendChild(b)});applyFont()}

  /* Equal card whitespace. */
  function readPadding(){var n=Number(localStorage.getItem(PADDING_KEY));return isFinite(n)?Math.max(0,Math.min(140,n)):0}
  function applyPadding(n){document.documentElement.style.setProperty('--welog-card-padding',Math.max(0,Math.min(140,Number(n)||0))+'px')}
  function ensurePaddingControl(){if(!controls)return;var anchor=controls.querySelector('.layout-ratio-controls');if(!anchor)return;var box=controls.querySelector('.welog-card-padding-control');if(!box){box=document.createElement('section');box.className='welog-card-padding-control';box.innerHTML='<div><b>카드 여백</b><span>현재 레이아웃 비율은 유지하고 상·하·좌·우 여백만 늘립니다.</span></div><label><input type="range" min="0" max="140" step="5" data-welog-card-padding><b data-welog-card-padding-value></b></label>';anchor.insertAdjacentElement('afterend',box)}var n=readPadding();box.querySelector('[data-welog-card-padding]').value=n;box.querySelector('[data-welog-card-padding-value]').textContent=n+'px';applyPadding(n)}

  /* Preview modal: shows only the final sheet, fitted inside a popup. */
  function ensurePreview(){var modal=document.getElementById('welogPreviewModal');if(modal)return modal;modal=document.createElement('div');modal.id='welogPreviewModal';modal.className='welog-preview-modal';modal.hidden=true;modal.innerHTML='<button class="welog-preview-backdrop" type="button" aria-label="미리보기 닫기"></button><section class="welog-preview-dialog"><header><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" data-preview-close>×</button></header><div class="welog-preview-viewport"><div class="welog-preview-holder"></div></div></section>';document.body.appendChild(modal);modal.querySelector('.welog-preview-backdrop').onclick=closePreview;modal.querySelector('[data-preview-close]').onclick=closePreview;return modal}
  function closePreview(){var modal=document.getElementById('welogPreviewModal');if(modal)modal.hidden=true;document.body.classList.remove('welog-preview-open')}
  async function openPreview(){await applyFont();renderConcepts();var modal=ensurePreview(),holder=modal.querySelector('.welog-preview-holder');holder.innerHTML='';var clone=sheet.cloneNode(true);clone.removeAttribute('id');clone.classList.add('welog-preview-sheet');clone.style.transform='none';clone.style.margin='0';holder.appendChild(clone);modal.hidden=false;document.body.classList.add('welog-preview-open');await applyFont();requestAnimationFrame(function(){var vw=modal.querySelector('.welog-preview-viewport'),r=clone.getBoundingClientRect(),maxW=Math.max(260,vw.clientWidth-40),maxH=Math.max(260,vw.clientHeight-40),scale=Math.min(1,maxW/r.width,maxH/r.height);clone.style.transform='scale('+scale+')';clone.style.transformOrigin='top left';holder.style.width=(r.width*scale)+'px';holder.style.height=(r.height*scale)+'px'})}

  async function exportPng(){if(!sheet||!window.html2canvas)return;saveBtn.disabled=true;saveBtn.textContent='저장 중…';try{await applyFont();renderConcepts();if(document.fonts&&document.fonts.ready)await document.fonts.ready;await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var canvas=await html2canvas(sheet,{scale:Math.max(1.5,window.devicePixelRatio||1),useCORS:true,allowTaint:false,backgroundColor:'#fff',logging:false,imageTimeout:15000,foreignObjectRendering:false});var a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=((readState().pairName||'WeLog').trim()||'WeLog')+'.png';document.body.appendChild(a);a.click();a.remove()}catch(e){console.error('WeLog PNG export failed',e);alert('PNG 저장에 실패했습니다.')}finally{saveBtn.disabled=false;saveBtn.textContent='↓ PNG 저장'}}

  function toast(msg){var t=document.querySelector('.welog-toast');if(!t){t=document.createElement('div');t.className='welog-toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(function(){t.classList.remove('show')},1800)}
  function loadTextOnlySlot(number){var item;try{item=JSON.parse(localStorage.getItem('welog-slot-'+number)||'null')}catch(e){}if(!item||!item.data)return false;var data=JSON.parse(JSON.stringify(item.data));data.pairImage='';data.pairImageLeft='';data.pairImageRight='';if(data.left)data.left.image='';if(data.right)data.right.image='';data.stickerAssets=[];data.stickers=[];if(!writeState(data))return false;location.reload();return true}

  if(controls){
    controls.addEventListener('input',function(e){var c=e.target.closest&&e.target.closest('input[data-concept-side]');if(c){e.preventDefault();e.stopImmediatePropagation();setSide(c.dataset.conceptSide,c.checked);return}if(e.target.matches('select[data-path="font"]')){var v=e.target.value;setTimeout(function(){saveFont(v)},0);return}if(e.target.matches('[data-welog-card-padding]')){var n=Number(e.target.value)||0,box=e.target.closest('.welog-card-padding-control');applyPadding(n);if(box)box.querySelector('[data-welog-card-padding-value]').textContent=n+'px'}},true);
    controls.addEventListener('change',function(e){if(e.target.matches('select[data-path="font"]')){var v=e.target.value;setTimeout(function(){saveFont(v)},0)}if(e.target.matches('[data-welog-card-padding]'))localStorage.setItem(PADDING_KEY,String(Number(e.target.value)||0))},true);
  }
  document.addEventListener('click',function(e){var load=e.target.closest&&e.target.closest('[data-slot-load]');if(load){e.preventDefault();e.stopImmediatePropagation();loadTextOnlySlot(load.dataset.slotLoad);return}var save=e.target.closest&&e.target.closest('[data-slot-save]');if(save)setTimeout(function(){toast('저장이 완료되었습니다!')},60)},true);
  if(saveBtn)saveBtn.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();exportPng()},true);
  if(previewBtn){previewBtn.hidden=false;previewBtn.textContent='미리보기';previewBtn.onclick=function(e){e.preventDefault();openPreview()}}

  var pending=false;function refresh(){pending=false;simplifyFontSelect();ensurePaddingControl();syncChecks();applyFont();renderConcepts()}function schedule(){if(pending)return;pending=true;setTimeout(refresh,0)}
  if(controls)new MutationObserver(schedule).observe(controls,{childList:true,subtree:false});
  if(sheet)new MutationObserver(function(){setTimeout(function(){applyFont();renderConcepts()},0)}).observe(sheet,{childList:true,subtree:false});
  Object.keys(defs).forEach(loadFont);applyPadding(readPadding());schedule();
})();